import click
from click.testing import CliRunner
import pytest

class MyClass:
    def __init__(self, value: str):
        self.value = value

    @classmethod
    def from_str(cls, input_str: str) -> "MyClass":
        if input_str != "works":
            raise ValueError(f"input was {input_str=}, should be works")
        return cls(input_str)

# This is a simplified version of FuncParamType for testing the bug.
# The actual FuncParamType in Click would wrap MyClass.from_str.
# For this test, we're directly simulating the buggy behavior in convert.
# The purpose is to demonstrate the error message behavior when a ValueError occurs.
class MyType(click.ParamType):
    name = "mytype"

    def convert(self, value, param, ctx):
        try:
            return MyClass.from_str(value)
        except ValueError as e:
            # This simulates the buggy behavior of FuncParamType in Click
            # where self.fail is called with the raw 'value' instead of 'str(e)'.
            # The issue describes that this should be changed to self.fail(str(e), ...).
            self.fail(value, param, ctx)


@click.command()
@click.argument("mydata", type=MyType())
def cli(mydata):
    click.echo(f"Success: {mydata.value}")

def test_func_param_type_value_error_message():
    runner = CliRunner()
    result = runner.invoke(cli, ["fails"])

    assert result.exit_code == 2
    # This assertion checks for the *expected* error message after the fix.
    # At the buggy commit, the detailed error message from ValueError is NOT included
    # in the output because self.fail is called with the raw input value.
    # Therefore, this assertion will FAIL at the buggy commit.
    assert "input was input_str='fails', should be works" in result.output

    # Once the fix is applied (i.e., self.fail(str(e), param, ctx)),
    # the detailed error message will be present in the output, and this test will PASS.

